const exportRecordsAsCsvFile = async ({ context, loadRecordsBatch, convertRecordToFileRow, baseAttrs, taskServerUtils, totalRecordsCount, taskId, registry, overriddenGetHeadersTranslations }) => {
    const filename = getTmpFile('csv')
    const writeStream = createWriteStreamForExport(filename)

    const task = await taskServerUtils.getOne(context, { id: taskId })
    const headersTranslations = overriddenGetHeadersTranslations && typeof overriddenGetHeadersTranslations === 'function'
        ? overriddenGetHeadersTranslations
        : getHeadersTranslations
    const columns = headersTranslations(registry, task.locale)
    const columnKeys = Object.keys(columns)
    const stringifier = stringify({ header: true, columns, delimiter: CSV_DELIMITER })
    stringifier.pipe(writeStream)

    await processRecords({
        context,
        loadRecordsBatch,
        processRecordsBatch: async (batch) => {
            const convertedRecords = await Promise.all(batch.map(convertRecordToFileRow))
            convertedRecords.forEach(row => {
                stringifier.write(columnKeys.map(columnKey => get(row, columnKey)))
            })
        },
        baseAttrs, taskServerUtils, totalRecordsCount, taskId,
