import { Popover as DefaultPopover } from 'antd'
import { Close } from '@open-condo/icons'
import React, { useEffect, useState } from 'react'

import { sendAnalyticsChangeEvent, sendAnalyticsClickEvent } from '../_utils/analytics'
import { Typography } from '../Typography'
import { useTourContext } from './tourContext'

import type { PopoverProps as DefaultPopoverProps } from 'antd'

export type TourStepProps = Pick<DefaultPopoverProps, 'className' | 'id' | 'destroyTooltipOnHide' | 'zIndex'> & {
    step: number
    title: string
    message: string
    onClose?: () => void
    children?: React.ReactNode
    placement?: 'top' | 'bottom' | 'left' | 'right'
}

export const TourStep = (props: TourStepProps): JSX.Element => {
    const { title, message, step, onClose, children, placement = 'top', ...otherProps } = props
    const { currentStep } = useTourContext()
    const [open, setOpen] = useState<boolean>(step === currentStep)

    useEffect(() => {
        setOpen(step === currentStep)
    }, [currentStep, step])

    useEffect(() => {
        if (open) {
            sendAnalyticsChangeEvent('TourStep', { title, message, step })
        }
    }, [open, title, message, step])

    const handleClose = () => {
        if (onClose) onClose()
        setOpen(false)
        sendAnalyticsClickEvent('TourStep', { title, message, step })
    }

    return (
        <DefaultPopover
            {...otherProps}
            title={(
                <>
                    <div className='condo-tour-close-icon-wrapper'>
                        <Close size='small' className='condo-tour-close-icon' onClick={handleClose}/>
                    </div>
                    <Typography.Title level={4}>
                        {title}
                    </Typography.Title>
                </>
            )}
            content={(
                <Typography.Text size='small'>
                    {message}
                </Typography.Text>
            )}
            open={open}
            showArrow
            arrowPointAtCenter
            prefixCls='condo-popover'
            trigger={[]}
            placement={placement}
        >
            {children}
        </DefaultPopover>
    )
}

