const { X509Certificate } = require('crypto')
const tls = require('tls')

const dayjs = require('dayjs')
const express = require('express')
const LRUCache = require('lru-cache')

const { getRedisClient } = require('./redis')

/**
 * Creates a health check for a third-party integration, which reports its health status
 * by running a given read-only business function (e.g. calling `getVersion` of an external API).
 *
 * The provided `getStatus` function is expected to return one of the following string constants:
 * - 'success' - integration is in a healthy state
 * - 'warn'    - integration is in a deteriorated state
 * - 'fail'    - integration is unavailable
 *
 * The check is considered to be passed only when the returned status is 'success'.
 * Any error thrown by `getStatus` will also cause the check to fail.
 *
 * @param {Object} options - configuration of the health check
 * @param {String} options.integrationName - integration name - to be appeared in health check results
 * @param {() => Promise<'success'|'warn'|'fail'>} options.getStatus - read-only business function that calls 3rd party API (getVersion or etc.).
 *                  Must return string constant (status): success|warn|fail
 * @returns {{name: String, run: (() => Promise<boolean>), prepare: (() => void)}} health check, which passes only if the integration status is 'success'
 * @throws {Error} If `integrationName` or `getStatus` is not provided
 */
const getIntegrationHealthCheck = ({ integrationName, getStatus }) => {
    if (!integrationName) throw new Error('Parameter integrationName required to be provided!')
    if (!getStatus) throw new Error('Parameter getStatus must be provided!')

    return {
        name: `${integrationName}_integration`,
        prepare: ({ keystone }) => {
            this.keystone = keystone
        },
        run: async () => {
            try {
                const status = await getStatus()
                return 'success' === status
            } catch (e) {
                console.error('Can not get integration status. ', e)
                return false
            }
        },
    }
}

/**
 * Creates a health check for a X.509 certificate, used by external integrations
 * (e.g. certificates of client applications for mTLS communication with third-party servers).
 *
 * The check validates that the certificate is present, correctly encoded and that the
 * certificate validity window contains the check date, shifted by the configured number
 * of days before the certificate expiration:
 * - the certificate has not expired yet
 * - the certificate is not about to expire within the `signalExpiryDaysBefore` days window
 * - the certificate validity has already started (check date is not earlier than `validFrom`)
 *
 * When the certificate is missing, cannot be parsed or does not satisfy the above conditions,
 * the check is considered to be failed.
 *
 * @param {Object} options - configuration of the health check
 * @param {String} options.certificateName - certificate name - to be appeared in health check results
 * @param {() => Promise<String|Buffer>} options.getCertificate - get parse able certificate content for X509Certificate
 * @param {Number} [options.signalExpiryDaysBefore=14] - start to signal about expiry earlier, configure number of days before
 * @returns {{name: String, run: (() => Promise<boolean>), prepare: (() => void)}} health check, which passes only if the certificate is valid and not about to expire within the signalized window
 * @throws {Error} If `certificateName` or `getCertificate` is not provided
 */
const getCertificateHealthCheck = ({ certificateName, getCertificate, signalExpiryDaysBefore = 14 }) => {
    if (!certificateName) throw new Error('Parameter certificateName required to be provided!')
    if (!getCertificate) throw new Error('Parameter getCertificate must be provided!')

    return {
        name: `${certificateName}_certificate`,
        prepare: ({ keystone }) => {
            this.keystone = keystone
        },
        run: async () => {
            try {
                const certificateInfo = new X509Certificate(await getCertificate())

                // calc days
                const validFrom = dayjs(certificateInfo.validFrom).unix()
                const validTo = dayjs(certificateInfo.validTo).unix()
                const checkDate = dayjs().add(signalExpiryDaysBefore, 'day').unix()

                // check if date inside window
                return checkDate >= validFrom && checkDate <= validTo
            } catch (e) {
                console.error('Can not extract certificate expiry date. ', e)
                return false
            }
        },
    }
}

/**
 * Creates a health check for a PFX (PKCS#12) certificate, used by external integrations
 * (e.g. SBBOL integration which stores the certificate in an encrypted PFX content).
 *
 * This check wraps the certificate health check created by `getCertificateHealthCheck`:
 * the embedded X.509 certificate is first extracted from the encrypted PFX content,
 * using the configured passphrase, and then validated against the expiration window.
 * When the encrypted content cannot be decrypted, the check is considered to be failed.
 *
 * @param {Object} options - configuration of the health check
 * @param {String} options.certificateName - certificate name - to be appeared in health check results
 * @param {() => Promise<{ pfx: String, passphrase: String }>} options.getPfxParams - function returning { pfx, passphrase } content
 * @param {Number} [options.signalExpiryDaysBefore=14] - start to signal about expiry earlier, configure number of days before
 * @returns {{name: String, run: (() => Promise<boolean>), prepare: (() => void)}} health check, which passes only if the certificate extracted from the PFX content is valid and not about to expire within the signalized window
 * @throws {Error} If `getPfxParams` is not provided
 */
const getPfxCertificateHealthCheck = ({ certificateName, getPfxParams, signalExpiryDaysBefore = 14 }) => {
    if (!getPfxParams) throw new Error('Parameter getPfxParams required to be provided!')

    const getCertificate = async () => {
        const { pfx, passphrase } = await getPfxParams()
        const context = tls.createSecureContext({
